export function toJsonString(value: unknown): string {
  return JSON.stringify(value);
}

function asObject(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return {};
  }

  return value as Record<string, unknown>;
}

function asString(value: unknown): string | undefined {
  if (typeof value === 'string' && value.trim().length > 0) {
    return value.trim();
  }
  return undefined;
}

function asFiniteNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }

  if (typeof value === 'string') {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) {
      return parsed;
    }
  }

  return null;
}

function normalizePostcode(value: string): string {
  return value.replace(/\s+/g, '').toUpperCase();
}

async function ensureUserExists(userId: string) {
  const result = await db.query<{ id: string }>(
    `
      SELECT id
      FROM users
      WHERE id = $1
      LIMIT 1
    `,
    [userId]
  );

  if (!result.rowCount) {
    throw createApiError('USER_NOT_FOUND', 'User account does not exist', {
      userId,
    });
  }
}

function ensureSecurityAdmin(headerToken: string | undefined) {
  if (!headerToken || headerToken !== config.apiSecurityAdminToken) {
    throw new Error('Missing or invalid security admin token');
  }
}

function resolveSingleHeader(
  value: string | string[] | undefined,
): string | undefined {
  return Array.isArray(value) ? value[0] : value;
}

function secureTokenMatches(
  candidate: string | undefined,
  expected: string,
): boolean {
  if (!candidate) {
    return false;
  }

  const candidateBuffer = Buffer.from(candidate);
  const expectedBuffer = Buffer.from(expected);
  return candidateBuffer.length === expectedBuffer.length
    && crypto.timingSafeEqual(candidateBuffer, expectedBuffer);
}

function authorizeInternalServiceRequest(request: FastifyRequest): boolean {
  return secureTokenMatches(
    resolveSingleHeader(request.headers['x-internal-service-token']),
    config.apiInternalServiceToken,
  );
}

function authorizeSecurityAdminRequest(request: FastifyRequest): boolean {
  return request.authUser?.role === 'admin'
    && secureTokenMatches(
      resolveSingleHeader(request.headers['x-security-admin-token']),
      config.apiSecurityAdminToken,
    );
}

function ensureSecurityAdminAccess(
  request: {
    headers: Record<string, string | string[] | undefined>;
    authUser?: AuthenticatedUser;
  },
  reply: {
    code: (statusCode: number) => unknown;
  }
): { ok: false; error: string } | null {
  try {
    ensureSecurityAdmin(request.headers['x-security-admin-token'] as string | undefined);
  } catch (error) {
    reply.code(401);
    return {
      ok: false,
      error: (error as Error).message,
    };
  }

  if (request.authUser && request.authUser.role !== 'admin') {
    reply.code(403);
    return {
      ok: false,
      error: 'Forbidden: admin role required',
    };
  }

  return null;
}

function roundTo(value: number, decimals: number): number {
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

function clampNumber(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function toSafeInteger(value: number): number {
  if (!Number.isFinite(value)) {
    return 0;
  }

  return Math.max(0, Math.round(value));
}

function ratioOrNull(numerator: number, denominator: number, decimals = 6): number | null {
  if (!Number.isFinite(numerator) || !Number.isFinite(denominator) || denominator <= 0) {
    return null;
  }

  return roundTo(numerator / denominator, decimals);
}

