function onezeAmountToMg(amount: number): number {
  const mg = Math.round(amount * ONEZE_MG_PER_IZE);
  if (!Number.isSafeInteger(mg) || mg <= 0) {
    throw createApiError('IZE_AMOUNT_INVALID', '1ze amount cannot be represented safely in mg units');
  }

  return mg;
}

function mgToOnezeAmount(amountMg: number): number {
  return Number((amountMg / ONEZE_MG_PER_IZE).toFixed(6));
}

function getFiatMinorDigits(currency: string): number {
  return currencyExponent(currency);
}

function toFiatMinor(amountMajor: number, currency: string): number {
  const digits = getFiatMinorDigits(currency);
  const factor = 10 ** digits;
  const minor = Math.round(amountMajor * factor);
  if (!Number.isSafeInteger(minor)) {
    throw createApiError('FIAT_AMOUNT_INVALID', 'Fiat amount cannot be represented safely in minor units');
  }

  return minor;
}

function fromFiatMinor(amountMinor: number, currency: string): number {
  const digits = getFiatMinorDigits(currency);
  const factor = 10 ** digits;
  return Number((amountMinor / factor).toFixed(Math.max(2, digits)));
}

function calculateCommercePlatformChargeGbp(subtotalGbp: number): number {
  const normalizedSubtotal = roundTo(Math.max(0, subtotalGbp), 2);
  if (normalizedSubtotal <= 0) {
    return 0;
  }

  const formulaCharge =
    normalizedSubtotal * COMMERCE_PLATFORM_CHARGE_RATE + COMMERCE_PLATFORM_CHARGE_FIXED_GBP;
  const minimumCharge = normalizedSubtotal * COMMERCE_PLATFORM_CHARGE_MIN_RATE;
  return roundTo(Math.max(formulaCharge, minimumCharge), 2);
}

function calculateAuctionPlatformFeeGbp(winningBidGbp: number): number {
  return roundTo(Math.max(0, winningBidGbp) * AUCTION_PLATFORM_FEE_RATE, 2);
}

function calculateWalletTopupFeeBreakdown(grossFiatAmount: number): {
  grossFiatAmount: number;
  platformFeeRate: number;
  platformFeeAmount: number;
  netFiatAmount: number;
} {
  const gross = roundTo(Math.max(0, grossFiatAmount), 6);
  const platformFeeAmount = roundTo(gross * WALLET_TOPUP_PLATFORM_FEE_RATE, 6);
  const netFiatAmount = roundTo(Math.max(0, gross - platformFeeAmount), 6);

  return {
    grossFiatAmount: gross,
    platformFeeRate: WALLET_TOPUP_PLATFORM_FEE_RATE,
    platformFeeAmount,
    netFiatAmount,
  };
}

// ── Canonical auction lifecycle resolver ──
// Precedence: cancelled_at > settled_at > winner terminal (Buy Now) > scheduled end > scheduled start > live

export type CanonicalLifecycle =
  | 'cancelled'
  | 'settled'
  | 'ended'
  | 'live'
  | 'upcoming';

export type TerminalReason =
  | 'cancelled'
  | 'settled'
  | 'buy_now'
  | 'scheduled_end'
  | null;

export interface CanonicalLifecycleInput {
  cancelledAt: string | null;
  settledAt: string | null;
  winnerBidderId: string | null;
  startsAt: string | Date;
  endsAt: string | Date;
  now?: Date;
}

export interface CanonicalLifecycleResult {
  lifecycle: CanonicalLifecycle;
  terminalReason: TerminalReason;
}

export function resolveCanonicalLifecycle(input: CanonicalLifecycleInput): CanonicalLifecycleResult {
  const now = (input.now ?? new Date()).getTime();
  const startsAt = new Date(input.startsAt).getTime();
  const endsAt = new Date(input.endsAt).getTime();

  // 1. Cancelled — highest precedence, overrides everything
  if (input.cancelledAt) {
    return { lifecycle: 'cancelled', terminalReason: 'cancelled' };
  }

  // 2. Settled — explicit settlement overrides date-based status
  if (input.settledAt) {
    return { lifecycle: 'settled', terminalReason: 'settled' };
  }

  // 3. Winner set (Buy Now terminal) — auction is ended regardless of dates
  if (input.winnerBidderId) {
    return { lifecycle: 'ended', terminalReason: 'buy_now' };
  }

  // 4. Scheduled end time passed
  if (endsAt <= now) {
    return { lifecycle: 'ended', terminalReason: 'scheduled_end' };
  }

  // 5. Not yet started
  if (startsAt > now) {
    return { lifecycle: 'upcoming', terminalReason: null };
  }

  // 6. Live
  return { lifecycle: 'live', terminalReason: null };
}

// ── Atomic idempotency claims ──

function computeRequestHash(payload: Record<string, unknown>): string {
  const canonical = JSON.stringify(payload, Object.keys(payload).sort());
  return crypto.createHash('sha256').update(canonical).digest('hex');
}

interface IdempotencyClaimResult {
  claimed: boolean;
  existing?: {
    responseStatus: number;
    responseBody: Record<string, unknown>;
    requestHash: string;
  };
}

async function claimIdempotency(
  client: { query: <T = any>(text: string, values?: any[]) => Promise<{ rows: T[] }> },
  opts: {
    idempotencyKey: string;
    operationType: 'bid' | 'buy_now';
    auctionId: string;
    userId: string;
    requestHash: string;
  }
): Promise<IdempotencyClaimResult> {
  // Attempt atomic insert. If the key already exists, ON CONFLICT returns the existing row.
  const result = await client.query<{
    id: number;
    response_status: number;
    response_body: Record<string, unknown>;
    request_hash: string;
  }>(
    `
      INSERT INTO auction_transaction_idempotency (idempotency_key, operation_type, auction_id, user_id, request_hash, response_status, response_body)
      VALUES ($1, $2, $3, $4, $5, 200, '{}'::jsonb)
      ON CONFLICT (auction_id, user_id, idempotency_key)
      DO UPDATE SET idempotency_key = EXCLUDED.idempotency_key
      RETURNING id, response_status, response_body, request_hash
    `,
    [opts.idempotencyKey, opts.operationType, opts.auctionId, opts.userId, opts.requestHash]
  );

  const row = result.rows[0];
  // If response_body is empty, this is a fresh claim (we just inserted)
  const isEmptyBody = !row.response_body || Object.keys(row.response_body).length === 0;
  if (isEmptyBody) {
    return { claimed: true };
  }
  // Existing claim with a stored response — replay it
  return {
    claimed: false,
    existing: {
      responseStatus: row.response_status,
      responseBody: row.response_body,
      requestHash: row.request_hash,
    },
  };
}

async function storeIdempotencyResponse(
  client: { query: <T = any>(text: string, values?: any[]) => Promise<{ rows: T[] }> },
  opts: {
    idempotencyKey: string;
    operationType: 'bid' | 'buy_now';
    auctionId: string;
    userId: string;
    responseStatus: number;
    responseBody: Record<string, unknown>;
  }
): Promise<void> {
  await client.query(
    `
      UPDATE auction_transaction_idempotency
      SET response_status = $2, response_body = $3
      WHERE idempotency_key = $1 AND auction_id = $4 AND user_id = $5
    `,
    [opts.idempotencyKey, opts.responseStatus, JSON.stringify(opts.responseBody), opts.auctionId, opts.userId]
  );
}

// Legacy alias for backward compatibility in non-auction contexts
function resolveAuctionStatus(startsAt: Date, endsAt: Date): 'upcoming' | 'live' | 'ended' {
  const now = Date.now();
  const start = startsAt.getTime();
  const end = endsAt.getTime();

  if (end <= now) {
    return 'ended';
  }

  if (start <= now && end > now) {
    return 'live';
  }

  return 'upcoming';
}

function parseQueryBoolean(value: unknown, fallback = false): boolean {
  if (typeof value === 'boolean') {
    return value;
  }

  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    if (normalized === 'true' || normalized === '1' || normalized === 'yes') {
      return true;
    }
    if (normalized === 'false' || normalized === '0' || normalized === 'no') {
      return false;
    }
  }

  return fallback;
}

function resolveHeaderString(value: string | string[] | undefined): string | null {
  if (Array.isArray(value)) {
    const first = value.find((entry) => typeof entry === 'string' && entry.trim().length > 0);
    return first?.trim() ?? null;
  }

  if (typeof value === 'string' && value.trim().length > 0) {
    return value.trim();
  }

  return null;
}

function resolveRequestIpAddress(request: { ip: string; headers: Record<string, string | string[] | undefined> }): string {
  return resolveClientIp(request.ip, request.headers['x-forwarded-for']);
}

function resolveRequestUserAgent(request: { headers: Record<string, string | string[] | undefined> }): string | null {
  return resolveHeaderString(request.headers['user-agent']);
}

async function appendComplianceAuditSafe(
  request: {
    id: string;
    ip: string;
    headers: Record<string, string | string[] | undefined>;
    authUser?: AuthenticatedUser;
    log: { error: (payload: unknown, message: string) => void };
  },
  input: {
    eventType: string;
    actorUserId?: string | null;
    subjectUserId?: string | null;
    payload?: Record<string, unknown>;
  }
) {
  try {
    await appendComplianceAuditEvent(db, {
      eventType: input.eventType,
      actorUserId: input.actorUserId ?? request.authUser?.userId ?? null,
      subjectUserId: input.subjectUserId ?? request.authUser?.userId ?? null,
      requestId: request.id,
      ipAddress: resolveRequestIpAddress(request),
      userAgent: resolveRequestUserAgent(request),
      payload: input.payload ?? {},
    });
  } catch (error) {
    request.log.error(
      {
        err: error,
        eventType: input.eventType,
        requestId: request.id,
      },
      'Failed to append compliance audit event'
    );
  }
}

interface ApiError extends Error {
  code: string;
  details?: Record<string, unknown>;
  statusCode?: number;
}

function createApiError(code: string, message: string, details?: Record<string, unknown>): ApiError {
  const error = new Error(message) as ApiError;
  error.code = code;
  error.statusCode = statusCodeForApiError(code);
  if (details) {
    error.details = details;
  }
  return error;
}

function getApiError(error: unknown): ApiError | null {
  if (!error || typeof error !== 'object') {
    return null;
  }

  if ('code' in error && typeof (error as { code?: unknown }).code === 'string') {
    return error as ApiError;
  }

  return null;
}

declare module 'fastify' {
  interface FastifyRequest {
    authUser?: AuthenticatedUser;
    rawBody?: string | Buffer;
    apiVersion?: ApiVersion;
    metricsStartNs?: bigint;
  }
}

const BODY_ACTOR_KEYS = [
  'userId',
  'buyerId',
  'sellerId',
  'bidderId',
  'bidderUserId',
  'holderUserId',
  'issuerId',
  'senderId',
] as const;

function getRoutePath(url: string) {
  return normalizedRoutePath(url);
}

function isSecurityMaintenanceRoute(method: string, path: string) {
  return method === 'POST' && /^\/security\/keys\/[^/]+\/rotate$/.test(path);
}

function isPublicRoute(method: string, path: string) {
  if (method === 'OPTIONS') {
    return true;
  }

  if (method === 'POST' && (path.startsWith('/webhooks/') || path.startsWith('/shipping/webhooks/'))) {
    return true;
  }

  const signature = `${method} ${path}`;
  const fixedPublicRoutes = new Set<string>([
    'GET /health',
    'GET /health/deep',
    'GET /metrics',
    'GET /listings',
    'GET /search/listings',
    'GET /feed/looks',
    'GET /oracle/gold/latest',
    'POST /auth/signup',
    'POST /auth/login',
    'POST /auth/refresh',
    'POST /auth/oauth/google',
    'POST /auth/oauth/apple',
    'POST /auth/magic-link/request',
    'POST /auth/magic-link/consume',
    'POST /auth/otp/request',
    'POST /auth/otp/verify',
    'POST /auth/password-reset/request',
    'POST /auth/password-reset/confirm',
    'POST /compliance/kyc/webhook',
    'POST /compliance/kyc/webhooks/stripe',
    // Authenticated by the dedicated service-token check in the route module.
    'POST /offers/sweep-expired',
  ]);

  if (fixedPublicRoutes.has(signature)) {
    return true;
  }

  if (isSecurityMaintenanceRoute(method, path)) {
    return true;
  }

  if (method === 'GET' && path === '/auctions') {
    return true;
  }

  if (method === 'GET' && path === '/auctions/home') {
    return true;
  }

  if (method === 'GET' && path === '/auctions/1ze-rates') {
    return true;
  }

  // Public discovery feeds — both use optional auth (request.authUser?.userId ?? null)
  // and only return published/active content for unauthenticated viewers.
  if (method === 'GET' && path === '/feed/home') {
    return true;
  }

  if (method === 'GET' && path === '/looks') {
    return true;
  }

  if (method === 'GET' && /^\/auctions\/(?!watchlist$)[^/]+$/.test(path)) {
    return true;
  }

  if (method === 'GET' && /^\/auctions\/[^/]+\/bids$/.test(path)) {
    return true;
  }

  if (method === 'GET' && (path === '/co-own/assets' || path.startsWith('/co-own/assets/'))) {
    return true;
  }

  if (method === 'GET' && path === '/co-own/corporate-actions') {
    return true;
  }

  if (method === 'GET' && path === '/feed/trending') {
    return true;
  }

  if (method === 'GET' && path === '/feed/home') {
    return true;
  }

  if (method === 'GET' && /^\/co-own\/assets\/[^/]+\/price-history$/.test(path)) {
    return true;
  }

  if (method === 'GET' && /^\/co-own\/corporate-actions\/[^/]+\/votes$/.test(path)) {
    return true;
  }

  if (method === 'GET' && /^\/users\/[^/]+\/profile$/.test(path)) {
    return true;
  }

  if (method === 'GET' && /^\/sellers\/[^/]+$/.test(path)) {
    return true;
  }

  if (method === 'GET' && /^\/sellers\/[^/]+\/reviews$/.test(path)) {
    return true;
  }

  if (method === 'GET' && /^\/users\/[^/]+\/follow-counts$/.test(path)) {
    return true;
  }

  if (method === 'GET' && /^\/users\/[^/]+\/followers$/.test(path)) {
    return true;
  }

  if (method === 'GET' && /^\/users\/[^/]+\/following$/.test(path)) {
    return true;
  }

  if (method === 'GET' && /^\/users\/[^/]+\/listings$/.test(path)) {
    return true;
  }

  if (method === 'GET' && (path === '/poster-stories' || path.startsWith('/poster-stories/'))) {
    return true;
  }

  if (method === 'GET' && /^\/users\/[^/]+\/poster-highlights$/.test(path)) {
    return true;
  }

  // Poster product tag clicks are public (no auth required) so anonymous
  // viewers can register engagement on published posters.
  if (method === 'POST' && /^\/posters\/[^/]+\/tags\/[^/]+\/click$/.test(path)) {
    return true;
  }

  // T03: Listing detail is publicly viewable for active/sold listings.
  // The route handler calls optionalAuthenticate and gates non-public
  // statuses (draft/paused/deleted) to the seller only.
  if (method === 'GET' && /^\/listings\/[^/]+$/.test(path)) {
    return true;
  }

  // T04: Policy documents are publicly viewable (published versions only).
  if (method === 'GET' && /^\/policies\/[^/]+$/.test(path)) {
    return true;
  }

  return false;
}

function getBearerToken(authHeader: string | undefined) {
  if (!authHeader) {
    return null;
  }

  const [scheme, token] = authHeader.split(' ');
  if (!scheme || !token || scheme.toLowerCase() !== 'bearer') {
    return null;
  }

  return token.trim();
}

async function authenticateRequest(requestPath: string, authHeader: string | undefined) {
  const token = getBearerToken(authHeader);
  if (!token) {
    return null;
  }

  const authUser = await verifyAccessToken(token);
  if (!authUser) {
    app.log.warn({ requestPath }, 'Rejected request with invalid access token');
  }

  return authUser;
}

async function optionalAuthenticate(request: { headers: Record<string, string | string[] | undefined>; authUser?: AuthenticatedUser }, requestPath: string) {
  if (request.authUser) {
    return;
  }

  const authHeader = request.headers.authorization;
  if (!authHeader) {
    return;
  }

  const token = getBearerToken(Array.isArray(authHeader) ? authHeader[0] : authHeader);
  if (!token) {
    return;
  }

  const authUser = await verifyAccessToken(token);
  if (authUser) {
    request.authUser = authUser;
  }
}

// Routes where the /users/:userId segment identifies the *target* user of the
// action (the actor is always request.authUser), so the actor-context check
// must not compare it against the authenticated user.
function isUserTargetRoute(method: string, path: string) {
  if (method === 'GET' && path === '/users/search') {
    return true;
  }

  const match = path.match(/^\/users\/[^/]+\/([^/]+)$/);
  if (!match) {
    return false;
  }

  const segment = match[1];
  if (method === 'GET') {
    return ['profile', 'follow-counts', 'followers', 'following', 'listings', 'poster-highlights'].includes(segment);
  }
  if (method === 'POST') {
    return ['follow', 'block', 'unblock', 'report'].includes(segment);
  }
  if (method === 'DELETE') {
    return segment === 'follow';
  }
  return false;
}

function resolveActorUserId(requestPath: string, request: { params?: unknown; body?: unknown }) {
  const params = request.params as Record<string, unknown> | undefined;
  if (params && typeof params.userId === 'string') {
    return params.userId;
  }

  const userPathMatch = requestPath.match(/^\/users\/([^/]+)/);
  if (userPathMatch?.[1] && userPathMatch[1] !== 'me') {
    return decodeURIComponent(userPathMatch[1]);
  }

  const body = request.body;
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return null;
  }

  const bodyRecord = body as Record<string, unknown>;
  for (const key of BODY_ACTOR_KEYS) {
    const value = bodyRecord[key];
    if (typeof value === 'string' && value.trim().length > 0) {
      return value;
    }
  }

  return null;
}

function resolveAuthenticatedUserId(
  request: { authUser?: AuthenticatedUser },
  requestedUserId?: string
): string {
  const authUser = request.authUser;
  if (!authUser) {
    throw createApiError('UNAUTHORIZED', 'Unauthorized');
  }

  if (requestedUserId && authUser.role !== 'admin' && requestedUserId !== authUser.userId) {
    throw createApiError('FORBIDDEN_USER_CONTEXT', 'Forbidden: user context mismatch', {
      authUserId: authUser.userId,
      requestedUserId,
    });
  }

  return requestedUserId ?? authUser.userId;
}

function statusCodeForApiError(code: string): number {
  if (code === 'ONEZE_OPERATIONS_HALTED' || code === 'RECONCILIATION_TABLES_UNAVAILABLE' || code === 'PAYOUTS_PAUSED') {
    return 503;
  }

  if (code === 'PAYMENT_PROVIDER_UNAVAILABLE' || code === 'SHIPPING_PROVIDER_UNAVAILABLE') {
    return 503;
  }

  if (code === 'PAYOUT_PROVIDER_UNAVAILABLE') {
    return 503;
  }

  if (code === 'UNAUTHORIZED') {
    return 401;
  }

  if (code === 'FORBIDDEN_USER_CONTEXT') {
    return 403;
  }

  if (code === 'ORDER_ACCESS_DENIED' || code === 'REFUND_REQUIRES_OPERATOR') {
    return 403;
  }

  if (code === 'ORDER_ACTION_NOT_ALLOWED' || code === 'RESOLUTION_ALREADY_OPEN' || code === 'REVIEW_ALREADY_EXISTS') {
    return 409;
  }

  if (code === 'IDEMPOTENCY_KEY_REUSED') {
    return 409;
  }

  if (code === 'NOTIFICATION_ACCESS_DENIED') {
    return 403;
  }

  if (code === 'NOTIFICATION_NOT_FOUND') {
    return 404;
  }

  if (code === 'INVALID_NOTIFICATION_CURSOR' || code === 'INVALID_PREFERENCE_CATEGORY') {
    return 400;
  }

  if (code.endsWith('_NOT_FOUND') || code === 'USER_NOT_FOUND') {
    return 404;
  }

  if (code.endsWith('_INVALID') || code.endsWith('_MISMATCH') || code.endsWith('_REQUIRED')) {
    return 400;
  }

  if (code.startsWith('P2P_TRANSFER_') && code.endsWith('_BLOCKED')) {
    return 403;
  }

  return 409;
}

app.addHook('onRequest', async (request) => {
  request.metricsStartNs = process.hrtime.bigint();

  const rawUrl = request.originalUrl ?? request.raw.url ?? request.url;
  const normalized = normalizeVersionedUrl(rawUrl);
  request.apiVersion = normalized.apiVersion;
});

app.addHook('onSend', async (request, reply, payload) => {
  reply.header('x-api-version', 'v1');
  reply.header('x-request-id', request.id);

  if (request.apiVersion === 'legacy') {
    reply.header('x-api-deprecation', 'Legacy unversioned endpoint; prefer /api/v1/*');
  }

  return payload;
});

app.addHook('onResponse', async (request, reply) => {
  if (!request.metricsStartNs) {
    return;
  }

  const elapsedNs = process.hrtime.bigint() - request.metricsStartNs;
  const routeTemplate =
    request.routeOptions.url
    ?? getRoutePath(request.raw.url ?? request.url);

  observeHttpRequest({
    method: request.method,
    route: routeTemplate,
    statusCode: reply.statusCode,
    durationSeconds: Number(elapsedNs) / 1_000_000_000,
  });
});

app.addHook('preHandler', async (request, reply) => {
  const requestPath = getRoutePath(request.raw.url ?? request.url);

  if (isPublicRoute(request.method, requestPath)) {
    return;
  }

  const authUser = await authenticateRequest(requestPath, request.headers.authorization);
  if (!authUser) {
    reply.code(401).send({
      ok: false,
      error: 'Unauthorized',
    });
    return reply;
  }

  request.authUser = authUser;

  // Apply per-user rate limiting after authentication succeeds.
  await userRateLimitHook(request, reply);
  if (reply.statusCode === 429) {
    return reply;
  }

  if (isUserTargetRoute(request.method, requestPath)) {
    return;
  }

  const actorUserId = resolveActorUserId(requestPath, request);
  if (actorUserId && authUser.role !== 'admin' && actorUserId !== authUser.userId) {
    reply.code(403).send({
      ok: false,
      error: 'Forbidden: user context mismatch',
    });
    return reply;
  }
});

app.setErrorHandler((error, request, reply) => {
  if (config.sentryDsn) {
    Sentry.captureException(error, {
      tags: {
        method: request.method,
        route: request.routeOptions.url,
      },
      extra: {
        requestId: request.id,
      },
    });
  }

  request.log.error(
    {
      err: error,
      method: request.method,
      path: request.raw.url,
      requestId: request.id,
    },
    'Unhandled request failure'
  );

  if (reply.sent) {
    return;
  }

  if (error instanceof z.ZodError) {
    reply.code(400);
    reply.send({
      ok: false,
      error: 'Invalid request payload',
      details: error.issues,
    });
    return;
  }

  // Fastify JSON Schema validation errors — return the same consistent
  // "Invalid request payload" response shape as Zod errors so clients
  // receive a uniform 400 regardless of which validation layer caught the
  // issue. The `validation` property is set by Fastify/Ajv when schema
  // validation fails (body, params, querystring, or headers).
  if ((error as { validation?: unknown }).validation) {
    reply.code(400);
    reply.send({
      ok: false,
      error: 'Invalid request payload',
    });
    return;
  }

  const statusCode =
    typeof (error as { statusCode?: unknown }).statusCode === 'number'
      ? (error as { statusCode: number }).statusCode
      : 500;
  const errorCode =
    typeof (error as { code?: unknown }).code === 'string'
      ? (error as { code: string }).code
      : undefined;

  reply.code(statusCode >= 400 ? statusCode : 500);
  const errorMessage = error instanceof Error ? error.message : 'Request failed';
  reply.send({
    ok: false,
    error: statusCode >= 500 ? 'Internal server error' : errorMessage,
    ...(errorCode ? { code: errorCode } : {}),
  });
});

type DbQueryable = Pick<PoolClient, 'query'>;
type LedgerOwnerType = 'platform' | 'user';
type LedgerAccountCode =
  | 'escrow_liability'
  | 'platform_revenue'
  | 'platform_operating'
  | 'seller_payable'
  | 'buyer_spend'
  | 'withdrawal_pending'
  | 'withdrawable_balance'
  | 'ize_wallet'
  | 'ize_pending_redemption'
  | 'ize_outstanding'
  | 'ize_fiat_received'
  | 'reserve_hold';
