// ── Block / unblock ──────────────────────────────────────────────────

app.post('/users/:userId/block', async (request, reply) => {
  if (!request.authUser) {
    reply.code(401);
    return { ok: false, error: 'Unauthorized' };
  }
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const { userId } = paramsSchema.parse(request.params);
  const blockerId = request.authUser.userId;

  if (blockerId === userId) {
    reply.code(400);
    return { ok: false, error: 'Cannot block yourself' };
  }

  const blockId = `block_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  await db.query(
    `INSERT INTO user_blocks (id, blocker_id, blocked_id, created_at)
     VALUES ($1, $2, $3, NOW())
     ON CONFLICT (blocker_id, blocked_id) DO NOTHING`,
    [blockId, blockerId, userId]
  );

  // Remove any follow relationship in either direction
  await db.query(
    `DELETE FROM user_follows WHERE (follower_id = $1 AND following_id = $2) OR (follower_id = $2 AND following_id = $1)`,
    [blockerId, userId]
  );

  return { ok: true, isBlocked: true };
});

app.post('/users/:userId/unblock', async (request, reply) => {
  if (!request.authUser) {
    reply.code(401);
    return { ok: false, error: 'Unauthorized' };
  }
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const { userId } = paramsSchema.parse(request.params);
  const blockerId = request.authUser.userId;

  await db.query(
    `DELETE FROM user_blocks WHERE blocker_id = $1 AND blocked_id = $2`,
    [blockerId, userId]
  );

  return { ok: true, isBlocked: false };
});

// ── Report user ──────────────────────────────────────────────────────

app.post('/users/:userId/report', async (request, reply) => {
  if (!request.authUser) {
    reply.code(401);
    return { ok: false, error: 'Unauthorized' };
  }
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const bodySchema = z.object({
    reason: z.enum(['spam', 'inappropriate', 'counterfeit', 'unresponsive', 'harassment', 'other']),
    details: z.string().min(1).max(2000).optional(),
  });
  const { userId } = paramsSchema.parse(request.params);
  const body = bodySchema.parse(request.body ?? {});
  const reporterId = request.authUser.userId;

  if (reporterId === userId) {
    reply.code(400);
    return { ok: false, error: 'Cannot report yourself' };
  }

  const reportId = `report_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  await db.query(
    `INSERT INTO user_reports (id, reporter_id, reported_id, reason, details, created_at, updated_at)
     VALUES ($1, $2, $3, $4, $5, NOW(), NOW())`,
    [reportId, reporterId, userId, body.reason, body.details ?? null]
  );

  reply.code(201);
  return { ok: true, reportId };
});

app.get('/users/search', async (request, reply) => {
  if (!request.authUser) {
    reply.code(401);
    return { ok: false, error: 'Unauthorized' };
  }

  const querySchema = z.object({
    q: z.string().trim().min(2).max(50),
    limit: z.coerce.number().int().min(1).max(20).default(20),
  });
  const { q, limit } = querySchema.parse(request.query ?? {});

  const result = await db.query<{ id: string; username: string; display_name: string | null; avatar: string | null }>(
    `
      SELECT id, username, display_name, avatar
      FROM users
      WHERE username ILIKE $1
      ORDER BY username ASC
      LIMIT $2
    `,
    [`%${q}%`, limit]
  );

  return {
    ok: true,
    items: result.rows.map((row) => ({
      id: row.id,
      username: row.username,
      displayName: row.display_name,
      avatar: row.avatar,
    })),
  };
});

app.post('/compliance/kyc/sessions', async (request, reply) => {
  const bodySchema = z.object({
    userId: z.string().min(2),
    vendor: z.string().trim().min(2).max(60).default(config.kycDefaultVendor),
    kycLevel: kycLevelSchema.default('basic'),
    requiredChecks: z.array(z.enum(['document', 'liveness', 'sanctions'])).min(1).max(3).default([
      'document',
      'liveness',
    ]),
    metadata: z.record(z.unknown()).optional(),
  });

  const payload = bodySchema.parse(request.body ?? {});

  if (payload.vendor !== 'stripe_identity') {
    reply.code(400);
    return {
      ok: false,
      error: 'Unsupported KYC provider',
      code: 'KYC_PROVIDER_UNSUPPORTED',
    };
  }

  if (payload.requiredChecks.includes('sanctions')) {
    reply.code(400);
    return {
      ok: false,
      error: 'Sanctions screening must be initiated through the AML screening flow',
      code: 'KYC_CHECK_UNSUPPORTED',
    };
  }

  if (!isKycProviderReady()) {
    reply.code(503);
    return {
      ok: false,
      error: 'KYC provider is unavailable',
      code: 'KYC_PROVIDER_NOT_CONFIGURED',
    };
  }

  await ensureUserExists(payload.userId);

  const caseId = createComplianceId('kyc_case');
  const userAgent = resolveRequestUserAgent(request);
  const ipAddress = resolveRequestIpAddress(request);
  let providerSession: Awaited<ReturnType<typeof createKycProviderSession>>;
  try {
    providerSession = await createKycProviderSession({
      caseId,
      userId: payload.userId,
      requireLiveness: payload.requiredChecks.includes('liveness'),
    });
  } catch (error) {
    request.log.error({ err: error, userId: payload.userId }, 'Failed creating KYC provider session');
    reply.code(503);
    return {
      ok: false,
      error: 'KYC provider is temporarily unavailable',
      code: 'KYC_PROVIDER_UNAVAILABLE',
    };
  }
  const kycVendorRef = providerSession.providerSessionId;

  const client = await db.connect();
  try {
    await client.query('BEGIN');

    const current = await getOrCreateComplianceProfile(client, payload.userId);

    await client.query(
      `
        UPDATE user_compliance_profiles
        SET
          kyc_status = 'pending',
          kyc_level = $2,
          kyc_vendor = $3,
          kyc_vendor_ref = $4,
          document_status = CASE
            WHEN document_status = 'approved' THEN document_status
            ELSE 'submitted'
          END,
          liveness_status = CASE
            WHEN liveness_status = 'passed' THEN liveness_status
            ELSE 'pending'
          END,
          trading_enabled = FALSE,
          metadata = metadata || $5::jsonb,
          updated_at = NOW()
        WHERE user_id = $1
      `,
      [
        payload.userId,
        payload.kycLevel,
        payload.vendor,
        kycVendorRef,
        toJsonString({
          latestKycCaseId: caseId,
          initiatedAt: new Date().toISOString(),
        }),
      ]
    );

    await client.query(
      `
        INSERT INTO kyc_cases (
          id,
          user_id,
          vendor,
          vendor_case_ref,
          status,
          kyc_level,
          required_checks,
          document_status,
          liveness_status,
          sanctions_status,
          payload
        )
        VALUES ($1, $2, $3, $4, 'pending', $5, $6::jsonb, 'submitted', 'pending', 'unknown', $7::jsonb)
      `,
      [
        caseId,
        payload.userId,
        payload.vendor,
        kycVendorRef,
        payload.kycLevel,
        toJsonString(payload.requiredChecks),
        toJsonString({
          requestedBy: request.authUser?.userId,
          userAgent,
          ipAddress,
          metadata: payload.metadata ?? {},
        }),
      ]
    );

    await client.query(
      `
        INSERT INTO kyc_verification_events (
          user_id,
          case_id,
          event_type,
          status,
          vendor,
          vendor_ref,
          payload,
          ip_address,
          user_agent
        )
        VALUES ($1, $2, 'session_created', 'pending', $3, $4, $5::jsonb, $6, $7)
      `,
      [
        payload.userId,
        caseId,
        payload.vendor,
        kycVendorRef,
        toJsonString({
          requiredChecks: payload.requiredChecks,
          previousStatus: current.kycStatus,
          metadata: payload.metadata ?? {},
        }),
        ipAddress,
        userAgent,
      ]
    );

    await client.query('COMMIT');
  } catch (error) {
    await client.query('ROLLBACK');
    try {
      await cancelKycProviderSession(providerSession.providerSessionId);
    } catch (cancellationError) {
      request.log.error(
        { err: cancellationError, providerSessionId: providerSession.providerSessionId },
        'Failed cancelling orphaned KYC provider session'
      );
    }
    throw error;
  } finally {
    client.release();
  }

  await appendComplianceAuditSafe(request, {
    eventType: 'kyc.session.created',
    subjectUserId: payload.userId,
    payload: {
      caseId,
      vendor: payload.vendor,
      kycLevel: payload.kycLevel,
      requiredChecks: payload.requiredChecks,
    },
  });

  reply.code(201);
  return {
    ok: true,
    kycSession: {
      id: caseId,
      userId: payload.userId,
      vendor: payload.vendor,
      status: 'pending',
      kycLevel: payload.kycLevel,
      requiredChecks: payload.requiredChecks,
      verificationUrl: providerSession.verificationUrl,
      providerSessionId: providerSession.providerSessionId,
    },
  };
});

app.post('/compliance/kyc/webhooks/stripe', async (request, reply) => {
  const rawBody =
    typeof request.rawBody === 'string'
      ? request.rawBody
      : request.rawBody
        ? request.rawBody.toString('utf8')
        : toJsonString(request.body ?? {});

  let event: ReturnType<typeof verifyKycProviderWebhook>;
  try {
    event = verifyKycProviderWebhook(rawBody, request.headers['stripe-signature']);
  } catch (error) {
    request.log.warn({ err: error }, 'Rejected KYC provider webhook');
    reply.code(400);
    return {
      ok: false,
      error: 'Invalid KYC webhook signature or payload',
      code: 'KYC_WEBHOOK_INVALID',
    };
  }

  if (!event) {
    return {
      ok: true,
      ignored: true,
    };
  }

  const caseStatus =
    event.decision === 'verified'
      ? 'verified'
      : event.decision === 'cancelled'
        ? 'cancelled'
        : 'pending';
  const profileKycStatus =
    event.decision === 'verified'
      ? 'verified'
      : event.decision === 'cancelled'
        ? 'rejected'
        : 'pending';
  const documentStatus =
    event.decision === 'verified'
      ? 'approved'
      : event.decision === 'requires_input'
        ? 'rejected'
        : 'submitted';
  const livenessStatus =
    event.decision === 'verified'
      ? 'passed'
      : event.decision === 'requires_input'
        ? 'failed'
        : 'pending';

  const client = await db.connect();
  try {
    await client.query('BEGIN');

    const webhookEvent = await client.query<{ id: number }>(
      `
        INSERT INTO kyc_verification_events (
          user_id,
          case_id,
          event_type,
          status,
          vendor,
          vendor_ref,
          provider_event_id,
          payload
        )
        VALUES ($1, $2, 'webhook_received', $3, 'stripe_identity', $4, $5, $6::jsonb)
        ON CONFLICT DO NOTHING
        RETURNING id
      `,
      [
        event.userId,
        event.caseId,
        event.decision,
        event.providerSessionId,
        event.providerEventId,
        toJsonString({
          eventType: event.rawType,
          lastErrorCode: event.lastErrorCode,
          lastErrorReason: event.lastErrorReason,
        }),
      ]
    );

    if (!webhookEvent.rowCount) {
      await client.query('COMMIT');
      return {
        ok: true,
        duplicate: true,
      };
    }

    const updatedCase = await client.query<{ id: string }>(
      `
        UPDATE kyc_cases
        SET
          status = $4,
          document_status = $5,
          liveness_status = $6,
          decision_reason = $7,
          payload = payload || $8::jsonb,
          completed_at = CASE WHEN $4 IN ('verified', 'cancelled') THEN NOW() ELSE NULL END,
          updated_at = NOW()
        WHERE id = $1
          AND user_id = $2
          AND vendor = 'stripe_identity'
          AND vendor_case_ref = $3
        RETURNING id
      `,
      [
        event.caseId,
        event.userId,
        event.providerSessionId,
        caseStatus,
        documentStatus,
        livenessStatus,
        event.lastErrorReason,
        toJsonString({
          latestProviderEventId: event.providerEventId,
          latestProviderEventType: event.rawType,
        }),
      ]
    );

    if (!updatedCase.rowCount) {
      throw createApiError('KYC_CASE_NOT_FOUND', 'KYC case not found for signed provider event');
    }

    await client.query(
      `
        UPDATE user_compliance_profiles
        SET
          kyc_status = $2,
          kyc_vendor = 'stripe_identity',
          kyc_vendor_ref = $3,
          document_status = $4,
          liveness_status = $5,
          trading_enabled = (
            $2 = 'verified'
            AND sanctions_status = 'clear'
            AND pep_status = 'clear'
          ),
          metadata = metadata || $6::jsonb,
          updated_at = NOW()
        WHERE user_id = $1
      `,
      [
        event.userId,
        profileKycStatus,
        event.providerSessionId,
        documentStatus,
        livenessStatus,
        toJsonString({
          latestKycProviderEventId: event.providerEventId,
          latestKycProviderEventAt: new Date().toISOString(),
        }),
      ]
    );

    await client.query('COMMIT');
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }

  await appendComplianceAuditSafe(request, {
    eventType: 'kyc.provider-webhook.processed',
    subjectUserId: event.userId,
    payload: {
      caseId: event.caseId,
      providerSessionId: event.providerSessionId,
      decision: event.decision,
    },
  });

  return {
    ok: true,
    duplicate: false,
    decision: event.decision,
  };
});

app.post('/compliance/kyc/webhook', async (request, reply) => {
  const securityAdminError = ensureSecurityAdminAccess(request, reply);
  if (securityAdminError) {
    return securityAdminError;
  }

  const bodySchema = z.object({
    userId: z.string().min(2),
    caseId: z.string().min(6).optional(),
    vendor: z.string().trim().min(2).max(60).default(config.kycDefaultVendor),
    kycStatus: kycStatusSchema.optional(),
    kycLevel: kycLevelSchema.optional(),
    documentStatus: documentStatusSchema.optional(),
    livenessStatus: livenessStatusSchema.optional(),
    sanctionsStatus: sanctionsStatusSchema.optional(),
    pepStatus: pepStatusSchema.optional(),
    amlRiskTier: amlRiskTierSchema.optional(),
    tradingEnabled: z.boolean().optional(),
    reason: z.string().max(300).optional(),
    payload: z.record(z.unknown()).optional(),
  });

  const payload = bodySchema.parse(request.body ?? {});

  if (config.nodeEnv === 'production' && /^(mock|sandbox)[_\-]/i.test(payload.vendor)) {
    reply.code(503);
    return {
      ok: false,
      error: 'KYC vendor is not configured for production',
      code: 'KYC_VENDOR_NOT_CONFIGURED',
    };
  }

  await ensureUserExists(payload.userId);

  const userAgent = resolveRequestUserAgent(request);
  const ipAddress = resolveRequestIpAddress(request);
  const effectiveCaseId = payload.caseId ?? createComplianceId('kyc_case');

  const client = await db.connect();
  try {
    await client.query('BEGIN');

    const current = await getOrCreateComplianceProfile(client, payload.userId);
    const nextKycStatus = payload.kycStatus ?? current.kycStatus;
    const nextKycLevel = payload.kycLevel ?? current.kycLevel;
    const nextDocumentStatus = payload.documentStatus ?? current.documentStatus;
    const nextLivenessStatus = payload.livenessStatus ?? current.livenessStatus;
    const nextSanctionsStatus = payload.sanctionsStatus ?? current.sanctionsStatus;
    const nextPepStatus = payload.pepStatus ?? current.pepStatus;
    const nextAmlRiskTier = payload.amlRiskTier ?? current.amlRiskTier;
    const nextTradingEnabled =
      payload.tradingEnabled
      ?? (
        nextKycStatus === 'verified'
        && nextDocumentStatus === 'approved'
        && nextLivenessStatus === 'passed'
        && nextSanctionsStatus === 'clear'
      );

    await client.query(
      `
        INSERT INTO kyc_cases (
          id,
          user_id,
          vendor,
          vendor_case_ref,
          status,
          kyc_level,
          required_checks,
          document_status,
          liveness_status,
          sanctions_status,
          decision_reason,
          payload,
          completed_at
        )
        VALUES (
          $1,
          $2,
          $3,
          $4,
          $5,
          $6,
          '["document","liveness","sanctions"]'::jsonb,
          $7,
          $8,
          $9,
          $10,
          $11::jsonb,
          CASE WHEN $5 IN ('verified', 'rejected', 'expired') THEN NOW() ELSE NULL END
        )
        ON CONFLICT (id)
        DO UPDATE
          SET
            status = EXCLUDED.status,
            kyc_level = EXCLUDED.kyc_level,
            document_status = EXCLUDED.document_status,
            liveness_status = EXCLUDED.liveness_status,
            sanctions_status = EXCLUDED.sanctions_status,
            decision_reason = EXCLUDED.decision_reason,
            payload = kyc_cases.payload || EXCLUDED.payload,
            completed_at = CASE
              WHEN EXCLUDED.status IN ('verified', 'rejected', 'expired') THEN NOW()
              ELSE kyc_cases.completed_at
            END,
            updated_at = NOW()
      `,
      [
        effectiveCaseId,
        payload.userId,
        payload.vendor,
        `${payload.vendor}:${effectiveCaseId}`,
        nextKycStatus === 'pending' ? 'pending' : nextKycStatus,
        nextKycLevel,
        nextDocumentStatus,
        nextLivenessStatus,
        nextSanctionsStatus,
        payload.reason ?? null,
        toJsonString(payload.payload ?? {}),
      ]
    );

    await client.query(
      `
        UPDATE user_compliance_profiles
        SET
          kyc_status = $2,
          kyc_level = $3,
          kyc_vendor = $4,
          kyc_vendor_ref = $5,
          document_status = $6,
          liveness_status = $7,
          sanctions_status = $8,
          pep_status = $9,
          aml_risk_tier = $10,
          trading_enabled = $11,
          metadata = metadata || $12::jsonb,
          updated_at = NOW()
        WHERE user_id = $1
      `,
      [
        payload.userId,
        nextKycStatus,
        nextKycLevel,
        payload.vendor,
        `${payload.vendor}:${effectiveCaseId}`,
        nextDocumentStatus,
        nextLivenessStatus,
        nextSanctionsStatus,
        nextPepStatus,
        nextAmlRiskTier,
        nextTradingEnabled,
        toJsonString({
          lastKycWebhookAt: new Date().toISOString(),
          lastKycCaseId: effectiveCaseId,
        }),
      ]
    );

    await client.query(
      `
        INSERT INTO kyc_verification_events (
          user_id,
          case_id,
          event_type,
          status,
          vendor,
          vendor_ref,
          payload,
          reviewer_user_id,
          ip_address,
          user_agent
        )
        VALUES ($1, $2, 'webhook_received', $3, $4, $5, $6::jsonb, $7, $8, $9)
      `,
      [
        payload.userId,
        effectiveCaseId,
        nextKycStatus,
        payload.vendor,
        `${payload.vendor}:${effectiveCaseId}`,
        toJsonString({
          reason: payload.reason ?? null,
          payload: payload.payload ?? {},
        }),
        request.authUser?.userId ?? null,
        ipAddress,
        userAgent,
      ]
    );

    if (payload.sanctionsStatus) {
      await client.query(
        `
          INSERT INTO sanctions_screenings (
            user_id,
            provider,
            screening_ref,
            status,
            matched_entities,
            payload
          )
          VALUES ($1, $2, $3, $4, $5::jsonb, $6::jsonb)
        `,
        [
          payload.userId,
          payload.vendor,
          `${payload.vendor}:${effectiveCaseId}`,
          payload.sanctionsStatus === 'unknown' ? 'error' : payload.sanctionsStatus,
          '[]',
          toJsonString(payload.payload ?? {}),
        ]
      );
    }

    await client.query('COMMIT');
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }

  const profile = await getOrCreateComplianceProfile(db, payload.userId);

  await appendComplianceAuditSafe(request, {
    eventType: 'kyc.webhook.processed',
    subjectUserId: payload.userId,
    payload: {
      caseId: effectiveCaseId,
      kycStatus: profile.kycStatus,
      sanctionsStatus: profile.sanctionsStatus,
      tradingEnabled: profile.tradingEnabled,
    },
  });

  return {
    ok: true,
    profile: toComplianceProfilePayload(profile),
  };
});

app.get('/compliance/kyc/:userId', async (request, reply) => {
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const querySchema = z.object({
    caseLimit: z.coerce.number().int().min(1).max(50).default(10),
    eventLimit: z.coerce.number().int().min(1).max(100).default(30),
  });

  const { userId } = paramsSchema.parse(request.params);
  const { caseLimit, eventLimit } = querySchema.parse(request.query);

  await ensureUserExists(userId);
  const profile = await getOrCreateComplianceProfile(db, userId);

  const cases = await db.query<{
    id: string;
    vendor: string;
    vendor_case_ref: string | null;
    status: string;
    kyc_level: string;
    document_status: string;
    liveness_status: string;
    sanctions_status: string;
    decision_reason: string | null;
    payload: Record<string, unknown>;
    created_at: string;
    updated_at: string;
    completed_at: string | null;
  }>(
    `
      SELECT
        id,
        vendor,
        vendor_case_ref,
        status,
        kyc_level,
        document_status,
        liveness_status,
        sanctions_status,
        decision_reason,
        payload,
        created_at::text,
        updated_at::text,
        completed_at::text
      FROM kyc_cases
      WHERE user_id = $1
      ORDER BY created_at DESC
      LIMIT $2
    `,
    [userId, caseLimit]
  );

  const events = await db.query<{
    id: number;
    case_id: string | null;
    event_type: string;
    status: string | null;
    vendor: string | null;
    vendor_ref: string | null;
    payload: Record<string, unknown>;
    reviewer_user_id: string | null;
    ip_address: string | null;
    user_agent: string | null;
    created_at: string;
  }>(
    `
      SELECT
        id,
        case_id,
        event_type,
        status,
        vendor,
        vendor_ref,
        payload,
        reviewer_user_id,
        ip_address,
        user_agent,
        created_at::text
      FROM kyc_verification_events
      WHERE user_id = $1
      ORDER BY created_at DESC
      LIMIT $2
    `,
    [userId, eventLimit]
  );

  return {
    ok: true,
    profile: toComplianceProfilePayload(profile),
    cases: cases.rows,
    events: events.rows,
  };
});

app.post('/compliance/aml/evaluate', async (request, reply) => {
  const bodySchema = z.object({
    userId: z.string().min(2),
    market: complianceMarketSchema,
    eventType: z.enum(['trade', 'bid', 'deposit', 'withdrawal', 'transfer', 'manual']).default('manual'),
    amountGbp: z.number().nonnegative(),
    relatedUserId: z.string().min(2).optional(),
    referenceId: z.string().min(2).max(80).optional(),
    ruleCode: z.string().max(80).optional(),
    notes: z.string().max(300).optional(),
    context: z.record(z.unknown()).optional(),
  });

  const payload = bodySchema.parse(request.body ?? {});
  await ensureUserExists(payload.userId);

  const assessment = await evaluateAmlRisk(db, {
    userId: payload.userId,
    market: payload.market,
    amountGbp: payload.amountGbp,
    counterpartyUserId: payload.relatedUserId,
  });

  let alert: { alertId: string; status: string } | null = null;

  if (assessment.shouldCreateAlert) {
    alert = await createAmlAlert(db, {
      userId: payload.userId,
      relatedUserId: payload.relatedUserId,
      market: payload.market,
      eventType: payload.eventType,
      amountGbp: payload.amountGbp,
      referenceId: payload.referenceId,
      ruleCode: payload.ruleCode,
      notes: payload.notes,
      context: payload.context,
      assessment,
    });
  }

  await appendComplianceAuditSafe(request, {
    eventType: 'aml.evaluated',
    subjectUserId: payload.userId,
    payload: {
      market: payload.market,
      eventType: payload.eventType,
      amountGbp: payload.amountGbp,
      riskScore: assessment.riskScore,
      riskLevel: assessment.riskLevel,
      alertId: alert?.alertId ?? null,
    },
  });

  return {
    ok: true,
    assessment,
    alert,
  };
});

app.get('/compliance/aml/alerts', async (request) => {
  const querySchema = z.object({
    userId: z.string().min(2).optional(),
    status: z.enum(['open', 'under_review', 'sar_required', 'sar_filed', 'dismissed']).optional(),
    limit: z.coerce.number().int().min(1).max(200).default(100),
  });

  const { userId, status, limit } = querySchema.parse(request.query);

  const result = await db.query<{
    id: string;
    user_id: string;
    related_user_id: string | null;
    market: string;
    event_type: string;
    risk_score: string;
    risk_level: string;
    status: string;
    amount_gbp: string | null;
    reference_id: string | null;
    rule_code: string | null;
    notes: string | null;
    context: Record<string, unknown>;
    reviewed_by: string | null;
    reviewed_at: string | null;
    sar_filed_at: string | null;
    created_at: string;
    updated_at: string;
  }>(
    `
      SELECT
        id,
        user_id,
        related_user_id,
        market,
        event_type,
        risk_score::text,
        risk_level,
        status,
        amount_gbp::text,
        reference_id,
        rule_code,
        notes,
        context,
        reviewed_by,
        reviewed_at::text,
        sar_filed_at::text,
        created_at::text,
        updated_at::text
      FROM aml_alerts
      WHERE ($1::text IS NULL OR user_id = $1)
        AND ($2::text IS NULL OR status = $2)
      ORDER BY created_at DESC
      LIMIT $3
    `,
    [userId ?? null, status ?? null, limit]
  );

  return {
    ok: true,
    items: result.rows.map((row) => ({
      id: row.id,
      userId: row.user_id,
      relatedUserId: row.related_user_id,
      market: row.market,
      eventType: row.event_type,
      riskScore: Number(row.risk_score),
      riskLevel: row.risk_level,
      status: row.status,
      amountGbp: row.amount_gbp === null ? null : Number(row.amount_gbp),
      referenceId: row.reference_id,
      ruleCode: row.rule_code,
      notes: row.notes,
      context: row.context,
      reviewedBy: row.reviewed_by,
      reviewedAt: row.reviewed_at,
      sarFiledAt: row.sar_filed_at,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    })),
  };
});

app.post('/compliance/aml/alerts/:alertId/review', async (request, reply) => {
  const securityAdminError = ensureSecurityAdminAccess(request, reply);
  if (securityAdminError) {
    return securityAdminError;
  }

  const paramsSchema = z.object({ alertId: z.string().min(4) });
  const bodySchema = z.object({
    status: z.enum(['under_review', 'sar_required', 'sar_filed', 'dismissed']),
    notes: z.string().max(300).optional(),
    jurisdictionCode: z.string().trim().min(2).max(12).optional(),
    narrative: z.string().max(2000).optional(),
    externalReportRef: z.string().max(120).optional(),
    metadata: z.record(z.unknown()).optional(),
  }).superRefine((value, ctx) => {
    if (value.status === 'sar_filed' && (!value.narrative || value.narrative.trim().length < 20)) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['narrative'],
        message: 'narrative with at least 20 characters is required when filing SAR',
      });
    }
  });

  const { alertId } = paramsSchema.parse(request.params);
  const payload = bodySchema.parse(request.body ?? {});

  const client = await db.connect();
  let resolvedUserId: string | null = null;

  try {
    await client.query('BEGIN');

    const alertUpdate = await client.query<{
      id: string;
      user_id: string;
      status: string;
    }>(
      `
        UPDATE aml_alerts
        SET
          status = $2,
          notes = COALESCE($3, notes),
          reviewed_by = $4,
          reviewed_at = NOW(),
          sar_filed_at = CASE WHEN $2 = 'sar_filed' THEN NOW() ELSE sar_filed_at END,
          updated_at = NOW()
        WHERE id = $1
        RETURNING id, user_id, status
      `,
      [alertId, payload.status, payload.notes ?? null, request.authUser?.userId ?? null]
    );

    if (!alertUpdate.rowCount) {
      await client.query('ROLLBACK');
      reply.code(404);
      return {
        ok: false,
        error: 'AML alert not found',
      };
    }

    resolvedUserId = alertUpdate.rows[0].user_id;

    if (payload.status === 'sar_filed') {
      const sarId = createComplianceId('sar');
      await client.query(
        `
          INSERT INTO compliance_sar_reports (
            id,
            alert_id,
            user_id,
            jurisdiction_code,
            status,
            narrative,
            external_report_ref,
            submitted_by,
            submitted_at,
            metadata
          )
          VALUES ($1, $2, $3, $4, 'submitted', $5, $6, $7, NOW(), $8::jsonb)
          ON CONFLICT (alert_id)
          DO UPDATE
            SET
              status = 'submitted',
              narrative = EXCLUDED.narrative,
              external_report_ref = EXCLUDED.external_report_ref,
              submitted_by = EXCLUDED.submitted_by,
              submitted_at = NOW(),
              metadata = compliance_sar_reports.metadata || EXCLUDED.metadata,
              updated_at = NOW()
        `,
        [
          sarId,
          alertId,
          resolvedUserId,
          payload.jurisdictionCode ?? null,
          payload.narrative,
          payload.externalReportRef ?? null,
          request.authUser?.userId ?? null,
          toJsonString(payload.metadata ?? {}),
        ]
      );
    }

    await client.query('COMMIT');
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }

  await appendComplianceAuditSafe(request, {
    eventType: 'aml.alert.reviewed',
    subjectUserId: resolvedUserId,
    payload: {
      alertId,
      status: payload.status,
      jurisdictionCode: payload.jurisdictionCode ?? null,
    },
  });

  return {
    ok: true,
    alertId,
    status: payload.status,
  };
});

