app.get('/users/me/export', async (request, reply) => {
  if (!request.authUser) {
    reply.code(401);
    return {
      ok: false,
      error: 'Unauthorized',
    };
  }

  const userId = request.authUser.userId;
  const gdprRequestId = createComplianceId('gdpr_export');
  const ipAddress = resolveRequestIpAddress(request);
  const userAgent = resolveRequestUserAgent(request);

  const client = await db.connect();

  try {
    await client.query('BEGIN');

    const userResult = await client.query<{
      id: string;
      username: string;
      email: string | null;
      role: string;
      email_verified_at: string | null;
      created_at: string;
      last_login_at: string | null;
      two_factor_enabled: boolean;
      is_erased: boolean;
      erased_at: string | null;
    }>(
      `
        SELECT
          id,
          username,
          email,
          role,
          email_verified_at::text,
          created_at::text,
          last_login_at::text,
          two_factor_enabled,
          is_erased,
          erased_at::text
        FROM users
        WHERE id = $1
        LIMIT 1
      `,
      [userId]
    );

    const user = userResult.rows[0];
    if (!user) {
      await client.query('ROLLBACK');
      reply.code(404);
      return {
        ok: false,
        error: 'User not found',
      };
    }

    await client.query(
      `
        INSERT INTO gdpr_requests (
          id,
          user_id,
          request_type,
          status,
          requested_ip,
          requested_user_agent,
          requested_at,
          payload
        )
        VALUES ($1, $2, 'export', 'processing', $3, $4, NOW(), '{}'::jsonb)
      `,
      [gdprRequestId, userId, ipAddress, userAgent]
    );

    const [
      addresses,
      paymentMethods,
      sessions,
      interactions,
      orders,
      auctionBids,
      coOwnOrders,
      coOwnHoldings,
      consents,
      profile,
      kycCases,
      amlAlerts,
      aiUsageEvents,
      gdprHistory,
    ] = await Promise.all([
      client.query('SELECT * FROM user_addresses WHERE user_id = $1 ORDER BY updated_at DESC', [userId]),
      client.query('SELECT * FROM user_payment_methods WHERE user_id = $1 ORDER BY updated_at DESC', [userId]),
      client.query('SELECT id, created_at, last_seen_at, revoked_at, user_agent, ip_address FROM user_sessions WHERE user_id = $1 ORDER BY created_at DESC', [userId]),
      client.query('SELECT * FROM interactions WHERE user_id = $1 ORDER BY created_at DESC LIMIT 1000', [userId]),
      client.query('SELECT * FROM orders WHERE buyer_id = $1 OR seller_id = $1 ORDER BY created_at DESC LIMIT 1000', [userId]),
      client.query('SELECT * FROM auction_bids WHERE bidder_id = $1 ORDER BY created_at DESC LIMIT 1000', [userId]),
      client.query('SELECT * FROM coOwn_orders WHERE user_id = $1 ORDER BY created_at DESC LIMIT 1000', [userId]),
      client.query('SELECT * FROM coOwn_holdings WHERE user_id = $1 ORDER BY updated_at DESC LIMIT 1000', [userId]),
      client.query('SELECT * FROM user_consents WHERE user_id = $1 ORDER BY accepted_at DESC LIMIT 1000', [userId]),
      client.query('SELECT * FROM user_compliance_profiles WHERE user_id = $1 LIMIT 1', [userId]),
      client.query('SELECT * FROM kyc_cases WHERE user_id = $1 ORDER BY created_at DESC LIMIT 500', [userId]),
      client.query('SELECT * FROM aml_alerts WHERE user_id = $1 ORDER BY created_at DESC LIMIT 500', [userId]),
      client.query(
        `SELECT
           id, conversation_id, bot_id, provider, model, status,
           input_tokens, output_tokens, total_tokens,
           estimated_cost_microusd, pricing_version, created_at
         FROM ai_usage_events
         WHERE user_id = $1
         ORDER BY created_at DESC
         LIMIT 1000`,
        [userId],
      ),
      client.query('SELECT id, request_type, status, requested_at, completed_at FROM gdpr_requests WHERE user_id = $1 ORDER BY requested_at DESC LIMIT 100', [userId]),
    ]);

    const exportPayload = {
      user,
      addresses: addresses.rows,
      paymentMethods: paymentMethods.rows,
      sessions: sessions.rows,
      interactions: interactions.rows,
      orders: orders.rows,
      auctionBids: auctionBids.rows,
      coOwnOrders: coOwnOrders.rows,
      coOwnHoldings: coOwnHoldings.rows,
      consents: consents.rows,
      complianceProfile: profile.rows[0] ?? null,
      kycCases: kycCases.rows,
      amlAlerts: amlAlerts.rows,
      aiUsageEvents: aiUsageEvents.rows,
      gdprHistory: gdprHistory.rows,
      exportedAt: new Date().toISOString(),
    };

    await client.query(
      `
        UPDATE gdpr_requests
        SET
          status = 'completed',
          completed_at = NOW(),
          payload = $2::jsonb,
          updated_at = NOW()
        WHERE id = $1
      `,
      [
        gdprRequestId,
        toJsonString({
          records: {
            addresses: addresses.rowCount ?? 0,
            paymentMethods: paymentMethods.rowCount ?? 0,
            sessions: sessions.rowCount ?? 0,
            interactions: interactions.rowCount ?? 0,
            orders: orders.rowCount ?? 0,
            auctionBids: auctionBids.rowCount ?? 0,
            coOwnOrders: coOwnOrders.rowCount ?? 0,
            coOwnHoldings: coOwnHoldings.rowCount ?? 0,
            consents: consents.rowCount ?? 0,
            kycCases: kycCases.rowCount ?? 0,
            amlAlerts: amlAlerts.rowCount ?? 0,
            aiUsageEvents: aiUsageEvents.rowCount ?? 0,
          },
        }),
      ]
    );

    await client.query('COMMIT');

    await appendComplianceAuditSafe(request, {
      eventType: 'gdpr.export.completed',
      subjectUserId: userId,
      payload: {
        gdprRequestId,
      },
    });

    return {
      ok: true,
      requestId: gdprRequestId,
      export: exportPayload,
    };
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }
});

app.delete('/users/me', async (request, reply) => {
  if (!request.authUser) {
    reply.code(401);
    return {
      ok: false,
      error: 'Unauthorized',
    };
  }

  const bodySchema = z.object({
    reason: z.string().max(500).optional(),
  });
  const payload = bodySchema.parse(request.body ?? {});

  const userId = request.authUser.userId;
  const gdprRequestId = createComplianceId('gdpr_erasure');
  const ipAddress = resolveRequestIpAddress(request);
  const userAgent = resolveRequestUserAgent(request);

  const client = await db.connect();

  try {
    await client.query('BEGIN');

    const userExists = await client.query('SELECT id FROM users WHERE id = $1 LIMIT 1', [userId]);
    if (!userExists.rowCount) {
      await client.query('ROLLBACK');
      reply.code(404);
      return {
        ok: false,
        error: 'User not found',
      };
    }

    await client.query(
      `
        INSERT INTO gdpr_requests (
          id,
          user_id,
          request_type,
          status,
          requested_ip,
          requested_user_agent,
          requested_at,
          payload
        )
        VALUES ($1, $2, 'erasure', 'processing', $3, $4, NOW(), $5::jsonb)
      `,
      [
        gdprRequestId,
        userId,
        ipAddress,
        userAgent,
        toJsonString({ reason: payload.reason ?? null }),
      ]
    );

    const anonymizedUsername = `deleted_user_${Date.now()}`;

    await client.query(
      `
        UPDATE users
        SET
          username = $2,
          email = NULL,
          password_hash = NULL,
          email_verified_at = NULL,
          last_login_at = NULL,
          two_factor_enabled = FALSE,
          is_erased = TRUE,
          erased_at = NOW(),
          deleted_at = NOW(),
          password_changed_at = NOW(),
          role = 'user'
        WHERE id = $1
      `,
      [userId, anonymizedUsername]
    );

    await client.query('DELETE FROM user_addresses WHERE user_id = $1', [userId]);
    await client.query('DELETE FROM user_payment_methods WHERE user_id = $1', [userId]);
    await client.query('DELETE FROM user_secure_profiles WHERE user_id = $1', [userId]);
    await client.query('DELETE FROM wallet_secure_snapshots WHERE user_id = $1', [userId]);
    await client.query('DELETE FROM secure_messages WHERE sender_id = $1 OR recipient_id = $1', [userId]);
    await client.query('DELETE FROM interactions WHERE user_id = $1', [userId]);
    await client.query('DELETE FROM recommendations WHERE user_id = $1', [userId]);
    await client.query('DELETE FROM recommendation_feedback WHERE user_id = $1', [userId]);
    await client.query('DELETE FROM notification_devices WHERE user_id = $1', [userId]);

    await client.query(
      `
        UPDATE notification_events
        SET
          title = '[erased]',
          body = '[erased]',
          payload = '{}'::jsonb,
          metadata = metadata || '{"gdprErased": true}'::jsonb
        WHERE user_id = $1
      `,
      [userId]
    );

    await client.query('DELETE FROM user_totp_factors WHERE user_id = $1', [userId]);
    await client.query('DELETE FROM user_recovery_codes WHERE user_id = $1', [userId]);
    await client.query('UPDATE user_sessions SET revoked_at = COALESCE(revoked_at, NOW()) WHERE user_id = $1', [userId]);
    await client.query('UPDATE refresh_tokens SET revoked_at = COALESCE(revoked_at, NOW()) WHERE user_id = $1', [userId]);
    await client.query('DELETE FROM password_reset_tokens WHERE user_id = $1', [userId]);

    await client.query(
      `
        UPDATE user_compliance_profiles
        SET
          legal_name = NULL,
          date_of_birth = NULL,
          kyc_status = 'expired',
          document_status = 'unsubmitted',
          liveness_status = 'unsubmitted',
          sanctions_status = 'unknown',
          pep_status = 'unknown',
          trading_enabled = FALSE,
          metadata = metadata || '{"gdprErased": true}'::jsonb,
          updated_at = NOW()
        WHERE user_id = $1
      `,
      [userId]
    );

    await client.query(
      `
        UPDATE gdpr_requests
        SET
          status = 'completed',
          completed_at = NOW(),
          resolution_notes = $2,
          updated_at = NOW()
        WHERE id = $1
      `,
      [gdprRequestId, 'User personal data anonymized and non-essential records erased']
    );

    await client.query('COMMIT');
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }

  await revokeAllUserSessions(userId);

  await appendComplianceAuditSafe(request, {
    eventType: 'gdpr.erasure.completed',
    subjectUserId: userId,
    payload: {
      gdprRequestId,
      reason: payload.reason ?? null,
    },
  });

  return {
    ok: true,
    requestId: gdprRequestId,
    message: 'Account personal data has been anonymized and compliance records retained.',
  };
});

app.get('/listings', async (request) => {
  const querySchema = z.object({
    category: z.string().optional(),
    brand: z.string().optional(),
    size: z.string().optional(),
    condition: z.string().optional(),
    minPrice: z.coerce.number().nonnegative().optional(),
    maxPrice: z.coerce.number().nonnegative().optional(),
    sort: z.enum(['newest', 'price_asc', 'price_desc']).optional().default('newest'),
    limit: z.coerce.number().int().min(1).max(200).optional().default(100),
    cursor: z.string().optional(),
  });
  const params = querySchema.parse(request.query ?? {});

  const conditions: string[] = ["status = 'active'"];
  const args: unknown[] = [];

  if (params.category) {
    conditions.push(`category = $${args.length + 1}`);
    args.push(params.category);
  }
  if (params.brand) {
    conditions.push(`brand ILIKE $${args.length + 1}`);
    args.push(`%${params.brand}%`);
  }
  if (params.size) {
    conditions.push(`size ILIKE $${args.length + 1}`);
    args.push(`%${params.size}%`);
  }
  if (params.condition) {
    conditions.push(`condition ILIKE $${args.length + 1}`);
    args.push(`%${params.condition}%`);
  }
  if (params.minPrice !== undefined) {
    conditions.push(`price_gbp >= $${args.length + 1}`);
    args.push(params.minPrice);
  }
  if (params.maxPrice !== undefined) {
    conditions.push(`price_gbp <= $${args.length + 1}`);
    args.push(params.maxPrice);
  }

  let cursorData: { sortValue: string | number; id: string } | null = null;
  if (params.cursor) {
    try {
      const decoded = JSON.parse(Buffer.from(params.cursor, 'base64').toString('utf-8'));
      cursorData = { sortValue: decoded.sortValue, id: decoded.id };
    } catch {
      // Invalid cursor — ignore it, start from beginning
    }
  }

  const orderBy =
    params.sort === 'price_asc'
      ? 'price_gbp ASC, l.id ASC'
      : params.sort === 'price_desc'
        ? 'price_gbp DESC, l.id DESC'
        : 'l.created_at DESC, l.id DESC';

  if (cursorData) {
    if (params.sort === 'price_asc') {
      conditions.push(`(price_gbp, l.id) > ($${args.length + 1}, $${args.length + 2})`);
      args.push(cursorData.sortValue, cursorData.id);
    } else if (params.sort === 'price_desc') {
      conditions.push(`(price_gbp, l.id) < ($${args.length + 1}, $${args.length + 2})`);
      args.push(cursorData.sortValue, cursorData.id);
    } else {
      conditions.push(`(l.created_at, l.id) < ($${args.length + 1}, $${args.length + 2})`);
      args.push(cursorData.sortValue, cursorData.id);
    }
  }

  const fetchLimit = params.limit + 1;

  const result = await readDb.query<{
    id: string;
    seller_id: string;
    title: string;
    description: string;
    price_gbp: number | string;
    image_url: string | null;
    status: string;
    category: string | null;
    brand: string | null;
    size: string | null;
    condition: string | null;
    original_price_gbp: number | string | null;
    created_at: string;
    seller_username: string | null;
  }>(
    `
      SELECT
        l.id, l.seller_id, l.title, l.description, l.price_gbp, l.image_url,
        l.status, l.category, l.brand, l.size, l.condition, l.original_price_gbp, l.created_at,
        u.username AS seller_username
      FROM listings l
      LEFT JOIN users u ON u.id = l.seller_id
      WHERE ${conditions.join(' AND ')}
      ORDER BY ${orderBy}
      LIMIT $${args.length + 1}
    `,
    [...args, fetchLimit]
  );

  const hasMore = result.rows.length > params.limit;
  const pageRows = hasMore ? result.rows.slice(0, params.limit) : result.rows;

  const listingIds = pageRows.map((r) => r.id);
  const imagesResult = listingIds.length
      ? await readDb.query<{
        listing_id: string;
        image_url: string;
        sort_order: number;
        media_width: number | null;
        media_height: number | null;
      }>(
        `SELECT
           listing_id,
           image_url,
           sort_order,
           NULLIF(to_jsonb(listing_images) ->> 'media_width', '')::integer AS media_width,
           NULLIF(to_jsonb(listing_images) ->> 'media_height', '')::integer AS media_height
         FROM listing_images
         WHERE listing_id = ANY($1)
         ORDER BY listing_id, sort_order`,
        [listingIds]
      )
    : { rows: [] };

  const imagesByListing = new Map<string, string[]>();
  const primaryGeometryByListing = new Map<string, { width: number; height: number } | null>();
  for (const img of imagesResult.rows) {
    const arr = imagesByListing.get(img.listing_id) ?? [];
    arr.push(img.image_url);
    imagesByListing.set(img.listing_id, arr);
    if (!primaryGeometryByListing.has(img.listing_id)) {
      primaryGeometryByListing.set(
        img.listing_id,
        img.media_width !== null && img.media_height !== null
          ? { width: img.media_width, height: img.media_height }
          : null,
      );
    }
  }

  const lastRow = pageRows[pageRows.length - 1];
  const nextCursor = hasMore && lastRow
    ? Buffer.from(JSON.stringify({
        sortValue: params.sort === 'price_asc' || params.sort === 'price_desc'
          ? Number(lastRow.price_gbp)
          : lastRow.created_at,
        id: lastRow.id,
      })).toString('base64')
    : undefined;

  return {
    items: pageRows.map((row) => {
      const primaryGeometry = primaryGeometryByListing.get(row.id);
      return {
        id: row.id,
        sellerId: row.seller_id,
        title: row.title,
        description: row.description,
        priceGbp: Number(row.price_gbp),
        imageUrl: row.image_url,
        images: imagesByListing.get(row.id) ?? (row.image_url ? [row.image_url] : []),
        mediaWidth: primaryGeometry?.width ?? null,
        mediaHeight: primaryGeometry?.height ?? null,
        mediaAspectRatio: primaryGeometry
          ? primaryGeometry.width / primaryGeometry.height
          : null,
        status: row.status,
        category: row.category,
        brand: row.brand,
        size: row.size,
        condition: row.condition,
        originalPriceGbp: row.original_price_gbp === null ? null : Number(row.original_price_gbp),
        createdAt: row.created_at,
        seller: row.seller_username
          ? {
              id: row.seller_id,
              username: row.seller_username,
              avatar: null,
              rating: null,
              reviewCount: null,
              location: null,
            }
          : null,
      };
    }),
    nextCursor,
  };
});

app.get('/search/listings', async (request) => {
  const querySchema = z.object({
    q: z.string().trim().min(2).max(120),
    limit: z.coerce.number().int().min(1).max(100).default(24),
    category: z.string().min(1).optional(),
    condition: z.string().min(1).optional(),
    size: z.string().min(1).optional(),
    priceMin: z.coerce.number().min(0).optional(),
    priceMax: z.coerce.number().min(0).optional(),
    sort: z.enum(['relevance', 'recent', 'price_asc', 'price_desc']).default('relevance'),
    page: z.coerce.number().int().min(1).max(100).default(1),
  });

  const { q, limit, category, condition, size, priceMin, priceMax, sort, page } =
    querySchema.parse(request.query);
  const searchPolicyVersion = 'listing-search-postgres-v3.0';
  const startTime = Date.now();

  // Build cache params from the normalized query
  const cacheParams: SearchQueryParams = {
    q,
    filters: {
      category,
      condition,
      size,
      priceMin,
      priceMax,
    },
    sort,
    page,
    limit,
  };

  // ── Cache-first read with stale-while-revalidate ──
  const revalidate = async (): Promise<void> => {
    const freshResult = await computeSearchResults(
      readDb, q, limit, category, condition, size, priceMin, priceMax, sort, page,
      searchPolicyVersion,
    );
    await setCachedSearchResult(redis, cacheParams, freshResult);
  };

  const cached = await getCachedOrRevalidate(redis, cacheParams, revalidate);
  if (cached) {
    const responseTimeMs = Date.now() - startTime;
    const zeroResults = cached.items.length === 0;

    // Track analytics (fire-and-forget)
    void recordSearchAnalytics(redis, {
      query: q,
      responseTimeMs,
      zeroResults,
      cacheHit: true,
    });
    void trackQueryFrequency(redis, q);

    return {
      ...cached,
      fromCache: true,
      responseTimeMs,
    };
  }

  // ── Cache miss: compute results from DB ──
  const computed = await computeSearchResults(
    readDb, q, limit, category, condition, size, priceMin, priceMax, sort, page,
    searchPolicyVersion,
  );

  const responseTimeMs = Date.now() - startTime;
  const zeroResults = computed.items.length === 0;

  // Cache the result (fire-and-forget, don't block response)
  void setCachedSearchResult(redis, cacheParams, computed);

  // Track analytics and query frequency (fire-and-forget)
  void recordSearchAnalytics(redis, {
    query: q,
    responseTimeMs,
    zeroResults,
    cacheHit: false,
  });
  void trackQueryFrequency(redis, q);

  return {
    ...computed,
    fromCache: false,
    responseTimeMs,
  };
});

/**
 * Compute search results from the database. Extracted as a helper
 * so it can be called both on cache miss and during background
 * revalidation.
 */
async function computeSearchResults(
  dbPool: typeof readDb,
  q: string,
  limit: number,
  category: string | undefined,
  condition: string | undefined,
  size: string | undefined,
  priceMin: number | undefined,
  priceMax: number | undefined,
  sort: string,
  page: number,
  searchPolicyVersion: string,
): Promise<Omit<CachedSearchResult, 'cachedAt' | 'fromCache' | 'stale'>> {
  const offset = (page - 1) * limit;

  // Build dynamic WHERE clause for filters
  const filterConditions: string[] = [];
  const filterArgs: unknown[] = [];
  let filterIdx = 2; // $1 is the query text

  if (category) {
    filterConditions.push(`l.category = $${filterIdx++}`);
    filterArgs.push(category);
  }
  if (condition) {
    filterConditions.push(`l.condition = $${filterIdx++}`);
    filterArgs.push(condition);
  }
  if (size) {
    filterConditions.push(`l.size = $${filterIdx++}`);
    filterArgs.push(size);
  }
  if (priceMin !== undefined) {
    filterConditions.push(`l.price_gbp >= $${filterIdx++}`);
    filterArgs.push(priceMin);
  }
  if (priceMax !== undefined) {
    filterConditions.push(`l.price_gbp <= $${filterIdx++}`);
    filterArgs.push(priceMax);
  }

  const filterClause = filterConditions.length > 0
    ? `AND ${filterConditions.join(' AND ')}`
    : '';

  // Determine ORDER BY based on sort option
  let orderBy: string;
  switch (sort) {
    case 'recent':
      orderBy = 'l.created_at DESC, l.id DESC';
      break;
    case 'price_asc':
      orderBy = 'l.price_gbp ASC, l.id DESC';
      break;
    case 'price_desc':
      orderBy = 'l.price_gbp DESC, l.id DESC';
      break;
    case 'relevance':
    default:
      orderBy = 'rank_score::numeric DESC, l.created_at DESC, l.id DESC';
      break;
  }

  const result = await dbPool.query<{
    id: string;
    seller_id: string;
    title: string;
    description: string;
    price_gbp: string;
    image_url: string | null;
    created_at: string;
    rank_score: string;
    seller_username: string | null;
  }>(
    `
      SELECT
        l.id,
        l.seller_id,
        l.title,
        l.description,
        l.price_gbp::text,
        l.image_url,
        l.created_at::text,
        ts_rank_cd(l.search_vector, websearch_to_tsquery('simple', $1))::text AS rank_score,
        u.username AS seller_username
      FROM listings l
      LEFT JOIN users u ON u.id = l.seller_id
      WHERE l.status = 'active'
        AND (
          l.search_vector @@ websearch_to_tsquery('simple', $1)
          OR POSITION(lower($1) IN lower(COALESCE(l.brand, ''))) > 0
          OR POSITION(lower($1) IN lower(COALESCE(l.category, ''))) > 0
          OR POSITION(lower($1) IN lower(COALESCE(l.size, ''))) > 0
          OR POSITION(lower($1) IN lower(COALESCE(l.condition, ''))) > 0
        )
        ${filterClause}
      ORDER BY ${orderBy}
      LIMIT $${filterIdx} OFFSET $${filterIdx + 1}
    `,
    [q, ...filterArgs, limit, offset]
  );

  if (result.rowCount && result.rowCount > 0) {
    return {
      ok: true,
      query: q,
      decision: {
        policyVersion: searchPolicyVersion,
        capabilityLevel: 'postgres_lexical',
        fallback: false,
      },
      items: result.rows.map((row) => ({
        id: row.id,
        sellerId: row.seller_id,
        title: row.title,
        description: row.description,
        priceGbp: Number(row.price_gbp),
        imageUrl: row.image_url,
        rank: Number(row.rank_score),
        createdAt: row.created_at,
        seller: row.seller_username
          ? {
              id: row.seller_id,
              username: row.seller_username,
              avatar: null,
              rating: null,
              reviewCount: null,
              location: null,
            }
          : null,
      })),
    };
  }

  // Fallback: ILIKE search when full-text search returns nothing
  const fallback = await dbPool.query<{
    id: string;
    seller_id: string;
    title: string;
    description: string;
    price_gbp: string;
    image_url: string | null;
    created_at: string;
    seller_username: string | null;
  }>(
    `
      SELECT l.id, l.seller_id, l.title, l.description, l.price_gbp::text, l.image_url, l.created_at::text,
        u.username AS seller_username
      FROM listings l
      LEFT JOIN users u ON u.id = l.seller_id
      WHERE l.status = 'active'
        AND (
          POSITION(lower($1) IN lower(l.title)) > 0
          OR POSITION(lower($1) IN lower(l.description)) > 0
          OR POSITION(lower($1) IN lower(COALESCE(l.brand, ''))) > 0
          OR POSITION(lower($1) IN lower(COALESCE(l.category, ''))) > 0
          OR POSITION(lower($1) IN lower(COALESCE(l.size, ''))) > 0
          OR POSITION(lower($1) IN lower(COALESCE(l.condition, ''))) > 0
        )
        ${filterClause}
      ORDER BY ${sort === 'price_asc' ? 'l.price_gbp ASC' : sort === 'price_desc' ? 'l.price_gbp DESC' : 'l.created_at DESC'}, l.id DESC
      LIMIT $${filterIdx} OFFSET $${filterIdx + 1}
    `,
    [q, ...filterArgs, limit, offset]
  );

  return {
    ok: true,
    query: q,
    fallback: true,
    decision: {
      policyVersion: searchPolicyVersion,
      capabilityLevel: 'postgres_lexical',
      fallback: true,
    },
    items: fallback.rows.map((row) => ({
      id: row.id,
      sellerId: row.seller_id,
      title: row.title,
      description: row.description,
      priceGbp: Number(row.price_gbp),
      imageUrl: row.image_url,
      rank: 0,
      createdAt: row.created_at,
      seller: row.seller_username
        ? {
            id: row.seller_id,
            username: row.seller_username,
            avatar: null,
            rating: null,
            reviewCount: null,
            location: null,
          }
        : null,
    })),
  };
}

// ── Autocomplete endpoint ─────────────────────────────────────────────────────

app.get('/search/autocomplete', async (request) => {
  const querySchema = z.object({
    q: z.string().trim().min(1).max(120),
    limit: z.coerce.number().int().min(1).max(20).default(8),
  });

  const { q, limit } = querySchema.parse(request.query);
  const startTime = Date.now();

  // Check autocomplete cache first
  const { getCachedAutocomplete, setCachedAutocomplete } = await import('./lib/searchCache.js');
  const cached = await getCachedAutocomplete(redis, q);
  if (cached) {
    return {
      ok: true,
      query: q,
      suggestions: cached.slice(0, limit),
      fromCache: true,
      responseTimeMs: Date.now() - startTime,
    };
  }

  // Query database for autocomplete suggestions
  const result = await readDb.query<{ term: string; frequency: string }>(
    `
      SELECT term, COUNT(*)::text AS frequency
      FROM (
        SELECT lower(l.title) AS term
        FROM listings l
        WHERE l.status = 'active' AND lower(l.title) LIKE lower($1 || '%')
        UNION ALL
        SELECT lower(COALESCE(l.brand, '')) AS term
        FROM listings l
        WHERE l.status = 'active' AND lower(COALESCE(l.brand, '')) LIKE lower($1 || '%')
        UNION ALL
        SELECT lower(COALESCE(l.category, '')) AS term
        FROM listings l
        WHERE l.status = 'active' AND lower(COALESCE(l.category, '')) LIKE lower($1 || '%')
      ) AS suggestions
      WHERE term != ''
      GROUP BY term
      ORDER BY frequency DESC
      LIMIT $2
    `,
    [q, limit]
  );

  const suggestions = result.rows.map((row) => ({
    text: row.term,
    type: 'query' as const,
    score: Number(row.frequency),
  }));

  // Cache the suggestions (fire-and-forget)
  void setCachedAutocomplete(redis, q, suggestions);

  return {
    ok: true,
    query: q,
    suggestions,
    fromCache: false,
    responseTimeMs: Date.now() - startTime,
  };
});

