app.post('/users/:userId/payout-accounts', async (request, reply) => {
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const bodySchema = z.object({
    gatewayId: z.string().min(2).max(80).optional(),
    providerAccountRef: z.string().min(3).max(140).optional(),
    countryCode: z.string().min(2).max(3).optional(),
    currency: z.string().length(3).optional(),
    status: z.enum(['pending', 'active', 'disabled']).default('pending'),
    metadata: z.record(z.unknown()).optional(),
  });

  const { userId } = paramsSchema.parse(request.params);
  resolveAuthenticatedUserId(request, userId);
  const payload = bodySchema.parse(request.body);

  if (!(await paymentTablesAvailable(db))) {
    reply.code(503);
    return {
      ok: false,
      error: 'Payment settlement tables are unavailable. Run migrations first.',
    };
  }

  await ensureUserExists(userId);

  const complianceProfile = await getOrCreateComplianceProfile(db, userId);
  const capabilities = resolveCountryCapabilities({
    countryCode: complianceProfile.countryCode,
    residencyCountryCode: complianceProfile.residencyCountryCode,
  });

  const payoutDefaults = resolvePayoutPolicyDefaults(capabilities, {
    gatewayId: payload.gatewayId,
    currency: payload.currency,
    countryCode: payload.countryCode,
    fallbackGatewayId: 'stripe_americas',
  });
  const resolvedCurrency = payoutDefaults.currency;
  const resolvedGatewayId = payoutDefaults.gatewayId;
  const resolvedCountryCode = payoutDefaults.countryCode;

  if (!isPayoutCurrencyAllowed(capabilities, resolvedCurrency)) {
    reply.code(400);
    return {
      ok: false,
      error: `Payout currency '${resolvedCurrency}' is unavailable for this country policy`,
    };
  }

  if (!isPayoutGatewayAllowed(capabilities, resolvedGatewayId)) {
    reply.code(400);
    return {
      ok: false,
      error: `Gateway '${resolvedGatewayId}' is unavailable for this country policy`,
    };
  }

  const gateway = await db.query<{ id: string }>(
    'SELECT id FROM payment_gateways WHERE id = $1 AND is_active = TRUE LIMIT 1',
    [resolvedGatewayId]
  );

  if (!gateway.rowCount) {
    reply.code(400);
    return {
      ok: false,
      error: 'Gateway is not available for payouts',
    };
  }

  if (!isGatewayConfigured(resolvedGatewayId)) {
    throw createApiError(
      'PAYOUT_PROVIDER_UNAVAILABLE',
      'The selected payout provider is not configured',
      { gatewayId: resolvedGatewayId }
    );
  }

  let providerAccountRef = payload.providerAccountRef?.trim() ?? null;
  let providerVerifiedStatus: 'pending' | 'active' = 'pending';

  if (resolvedGatewayId === 'stripe_americas') {
    if (!stripe) {
      throw createApiError(
        'PAYOUT_PROVIDER_UNAVAILABLE',
        'Stripe Connect is not configured'
      );
    }

    const connectAccount = await db.query<{ stripe_account_id: string }>(
      `SELECT stripe_account_id
       FROM stripe_connect_accounts
       WHERE user_id = $1
       LIMIT 1`,
      [userId]
    );
    const connectedAccountId = connectAccount.rows[0]?.stripe_account_id;
    if (!connectedAccountId) {
      throw createApiError(
        'PAYOUT_ONBOARDING_REQUIRED',
        'Complete Stripe payout onboarding before creating a payout account'
      );
    }
    if (providerAccountRef && providerAccountRef !== connectedAccountId) {
      throw createApiError(
        'PAYOUT_ACCOUNT_MISMATCH',
        'Payout account does not match the connected Stripe account'
      );
    }

    const providerAccount = await stripe.accounts.retrieve(connectedAccountId);
    if (
      providerAccount.metadata?.userId
      && providerAccount.metadata.userId !== userId
    ) {
      throw createApiError(
        'PAYOUT_ACCOUNT_MISMATCH',
        'Connected payout account ownership could not be verified'
      );
    }

    providerAccountRef = connectedAccountId;
    providerVerifiedStatus = providerAccount.payouts_enabled ? 'active' : 'pending';
  } else if (!providerAccountRef) {
    throw createApiError(
      'PAYOUT_PROVIDER_ACCOUNT_REQUIRED',
      'A verified provider payout account reference is required',
      { gatewayId: resolvedGatewayId }
    );
  }

  const result = await db.query<{
    id: number;
    user_id: string;
    gateway_id: string;
    provider_account_ref: string;
    country_code: string | null;
    currency: string;
    status: 'pending' | 'active' | 'disabled';
    metadata: Record<string, unknown>;
    created_at: string;
    updated_at: string;
  }>(
    `
      INSERT INTO payout_accounts (
        user_id,
        gateway_id,
        provider_account_ref,
        country_code,
        currency,
        status,
        metadata
      )
      VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb)
      ON CONFLICT (gateway_id, provider_account_ref)
      DO UPDATE SET
        country_code = EXCLUDED.country_code,
        currency = EXCLUDED.currency,
        status = EXCLUDED.status,
        metadata = payout_accounts.metadata || EXCLUDED.metadata,
        updated_at = NOW()
      WHERE payout_accounts.user_id = EXCLUDED.user_id
      RETURNING
        id,
        user_id,
        gateway_id,
        provider_account_ref,
        country_code,
        currency,
        status,
        metadata,
        created_at,
        updated_at
    `,
    [
      userId,
      resolvedGatewayId,
      providerAccountRef,
      resolvedCountryCode,
      resolvedCurrency,
      providerVerifiedStatus,
      toJsonString({
        ...(payload.metadata ?? {}),
        countryCluster: capabilities.countryCluster,
        capabilityPolicyVersion: capabilities.policyVersion,
        providerVerifiedAt:
          providerVerifiedStatus === 'active' ? new Date().toISOString() : null,
      }),
    ]
  );

  if (!result.rowCount) {
    throw createApiError(
      'PAYOUT_ACCOUNT_MISMATCH',
      'Payout account is already linked to another user'
    );
  }

  reply.code(201);
  return {
    ok: true,
    item: {
      id: result.rows[0].id,
      userId: result.rows[0].user_id,
      gatewayId: result.rows[0].gateway_id,
      providerAccountRef: result.rows[0].provider_account_ref,
      countryCode: result.rows[0].country_code,
      currency: result.rows[0].currency,
      status: result.rows[0].status,
      metadata: result.rows[0].metadata,
      createdAt: result.rows[0].created_at,
      updatedAt: result.rows[0].updated_at,
    },
  };
});

